"""agents.TabularAgent: the corridor recording passes the Agent check via the replay double."""

from rllab.agents import TabularAgent
from rllab.core import ActionSpace, Agent, TeamSpec

SYMBOL = "agents.TabularAgent"


def test_samples_follow_the_schema(codec):
    codec.assert_samples_valid(SYMBOL)


def test_recording_passes_the_agent_check(codec, tmp_path):
    fake = codec.fake("core.Agent")
    recording = codec.sample(SYMBOL, "corridor_5", fake.AgentRecording)
    assert recording.team == TeamSpec(1, (10,), ActionSpace("discrete", n=2))
    assert sum(call.kind == "learn" for call in recording.calls) == 5
    fake.check_agent(fake.ReplayAgent(recording), recording, tmp_path)


def test_tabular_agent_is_an_agent():
    assert Agent in TabularAgent.__mro__
